materialization_cost_direct.zig:
//! Canonical hash-consed direct-polynomial DAG accounting.
//!
//! Node creation and root folding occupy distinct, monotonically ordered
//! events. That distinction is required when an already-interned node is
//! folded as a later root: its lifetime extends to that fold even though no
//! new node is produced.

const std = @import("std");
const fixed_direct = @import("materialization_fixed_direct.zig");
const types = @import("types.zig");

pub const Error = std.mem.Allocator.Error || error{CountOverflow};

const materialized_column_namespace: u64 = @as(u64, 1) << 63;

pub const Op = enum(u8) {
    constant,
    committed,
    fixed_committed,
    row_mask,
    add,
    sub,
    neg,
    mul,
};

pub const Node = struct {
    op: Op,
    lhs: u32 = 0,
    rhs: u32 = 0,
    value: u64 = 0,
    namespace_digest: fixed_direct.Digest = [_]u8{0} ** 32,
};

pub const RootUse = struct {
    node: u32,
    fold_event: usize,
};

pub const OperationCounts = struct {
    additions: u64 = 0,
    subtractions: u64 = 0,
    negations: u64 = 0,
    multiplications: u64 = 0,
    committed: u64 = 0,
};

pub const Arena = struct {
    allocator: std.mem.Allocator,
    nodes: std.ArrayList(Node),
    creation_events: std.ArrayList(usize),
    interned: std.AutoHashMap(Node, u32),
    event_clock: usize,

    pub fn init(allocator: std.mem.Allocator) Arena {
        return .{
            .allocator = allocator,
            .nodes = .empty,
            .creation_events = .empty,
            .interned = std.AutoHashMap(Node, u32).init(allocator),
            .event_clock = 0,
        };
    }

    pub fn deinit(self: *Arena) void {
        self.interned.deinit();
        self.creation_events.deinit(self.allocator);
        self.nodes.deinit(self.allocator);
        self.* = undefined;
    }

    pub fn nodeCount(self: *const Arena) usize {
        return self.nodes.items.len;
    }

    pub fn intern(self: *Arena, node: Node) Error!u32 {
        if (self.interned.get(node)) |existing| return existing;
        const id = std.math.cast(u32, self.nodes.items.len) orelse
            return error.CountOverflow;
        const creation_event = std.math.add(usize, self.event_clock, 1) catch
            return error.CountOverflow;
        try self.nodes.append(self.allocator, node);
        errdefer _ = self.nodes.pop();
        try self.creation_events.append(self.allocator, creation_event);
        errdefer _ = self.creation_events.pop();
        try self.interned.put(node, id);
        self.event_clock = creation_event;
        return id;
    }

    pub fn committed(
        self: *Arena,
        value: types.ValueId,
        materialized: bool,
    ) Error!u32 {
        var identity_value: u64 = @intFromEnum(value);
        if (materialized) identity_value |= materialized_column_namespace;
        return self.intern(.{ .op = .committed, .value = identity_value });
    }

    pub fn fixedCommitted(
        self: *Arena,
        namespace_digest: fixed_direct.Digest,
        tree: fixed_direct.CommitmentTree,
        resolved: u64,
    ) Error!u32 {
        return self.intern(.{
            .op = .fixed_committed,
            .lhs = @intFromEnum(tree),
            .value = resolved,
            .namespace_digest = namespace_digest,
        });
    }

    pub fn binary(self: *Arena, op: Op, lhs: u32, rhs: u32) Error!u32 {
        var node = Node{ .op = op, .lhs = lhs, .rhs = rhs };
        if ((op == .add or op == .mul) and node.rhs < node.lhs)
            std.mem.swap(u32, &node.lhs, &node.rhs);
        return self.intern(node);
    }

    /// Records the ordered event at which a root is folded into an accumulator.
    pub fn recordRoot(self: *Arena, node: u32) Error!RootUse {
        if (node >= self.nodes.items.len) return error.CountOverflow;
        const fold_event = std.math.add(usize, self.event_clock, 1) catch
            return error.CountOverflow;
        self.event_clock = fold_event;
        return .{ .node = node, .fold_event = fold_event };
    }

    pub fn operationCounts(self: *const Arena) error{CountOverflow}!OperationCounts {
        var result = OperationCounts{};
        for (self.nodes.items) |node| switch (node.op) {
            .constant, .row_mask => {},
            .committed, .fixed_committed => result.committed = try checkedAdd(result.committed, 1),
            .add => result.additions = try checkedAdd(result.additions, 1),
            .sub => result.subtractions = try checkedAdd(result.subtractions, 1),
            .neg => result.negations = try checkedAdd(result.negations, 1),
            .mul => result.multiplications = try checkedAdd(result.multiplications, 1),
        };
        return result;
    }

    /// Peak live values under canonical first-intern production and the
    /// explicitly recorded root-fold schedule.
    pub fn peakLiveNodes(
        self: *const Arena,
        scratch_allocator: std.mem.Allocator,
        roots: []const RootUse,
    ) Error!u64 {
        if (self.nodes.items.len == 0) return 0;
        if (self.creation_events.items.len != self.nodes.items.len)
            return error.CountOverflow;

        const last_use = try scratch_allocator.dupe(usize, self.creation_events.items);
        defer scratch_allocator.free(last_use);
        for (self.nodes.items, self.creation_events.items) |node, consumer_event| {
            switch (node.op) {
                .constant, .committed, .fixed_committed, .row_mask => {},
                .add, .sub, .mul => {
                    if (node.lhs >= last_use.len or node.rhs >= last_use.len)
                        return error.CountOverflow;
                    last_use[node.lhs] = @max(last_use[node.lhs], consumer_event);
                    last_use[node.rhs] = @max(last_use[node.rhs], consumer_event);
                },
                .neg => {
                    if (node.lhs >= last_use.len) return error.CountOverflow;
                    last_use[node.lhs] = @max(last_use[node.lhs], consumer_event);
                },
            }
        }
        for (roots) |root| {
            if (root.node >= last_use.len or root.fold_event > self.event_clock)
                return error.CountOverflow;
            last_use[root.node] = @max(last_use[root.node], root.fold_event);
        }

        const event_count = std.math.add(usize, self.event_clock, 1) catch
            return error.CountOverflow;
        const releases = try scratch_allocator.alloc(u64, event_count);
        defer scratch_allocator.free(releases);
        @memset(releases, 0);
        for (last_use) |event| {
            if (event == 0 or event > self.event_clock) return error.CountOverflow;
            releases[event] = try checkedAdd(releases[event], 1);
        }

        var next_birth: usize = 0;
        var live: u64 = 0;
        var peak: u64 = 0;
        for (1..event_count) |event| {
            if (next_birth < self.creation_events.items.len and
                self.creation_events.items[next_birth] == event)
            {
                live = try checkedAdd(live, 1);
                peak = @max(peak, live);
                next_birth += 1;
            }
            live = std.math.sub(u64, live, releases[event]) catch
                return error.CountOverflow;
        }
        if (next_birth != self.nodes.items.len or live != 0)
            return error.CountOverflow;
        return peak;
    }
};

fn checkedAdd(lhs: u64, rhs: u64) error{CountOverflow}!u64 {
    return std.math.add(u64, lhs, rhs) catch error.CountOverflow;
}

materialization_direct_program.zig:
//! Owned canonical direct-polynomial program for one materialization cut.
//!
//! The program is the single lowering authority for the globally hash-consed
//! fixed-prefix, candidate-equality, fixed-suffix DAG measured by the H-009
//! cost model. Node order is first-intern order. Root uses retain their exact
//! fold events, including repeated or late uses of an already-interned node.
//! Candidate mappings make the semantic-value to physical-column boundary
//! explicit without changing the direct-node identity used by H-009.

const std = @import("std");
const direct = @import("materialization_cost_direct.zig");
const expr = @import("expr.zig");
const fixed = @import("materialization_fixed_direct.zig");
const identity = @import("degree3_materializer_identity.zig");
const ir = @import("ir.zig");
const types = @import("types.zig");
const validator = @import("validate.zig");

pub const Digest = [32]u8;
pub const Policy = identity.Policy;
pub const Op = direct.Op;
pub const Node = direct.Node;
pub const RootUse = direct.RootUse;
pub const CommitmentTree = fixed.CommitmentTree;
pub const format_version: u16 = 1;
pub const digest_domain =
    "stwo-zig/typed-air/materialization-direct-program-v1";

pub const Request = struct {
    gate: ?types.ValueId,
    policy: Policy = .{},
    /// Strictly increasing semantic values, in equality evaluation order.
    selected: []const types.ValueId,
    /// Physical start of the contiguous candidate materialization block.
    materialization_column_start: u64,
    fixed_direct_program: ?fixed.Program = null,
};

pub const MaterializedColumn = struct {
    source_value: types.ValueId,
    tree: fixed.CommitmentTree,
    physical_column: u64,
    direct_node: u32,
};

pub const StructuralCounts = struct {
    nodes: u64,
    root_uses: u64,
    additions: u64,
    subtractions: u64,
    negations: u64,
    multiplications: u64,
    unique_committed_column_reads: u64,
    streaming_peak_live_nodes: u64,
};

pub const ValidationError = error{
    CountOverflow,
    FixedColumnAliasesMaterialization,
    InvalidGate,
    InvalidGateType,
    InvalidSelectedValue,
    InvalidSelectedValueType,
    MaterializationColumnStartMismatch,
    MissingDirectOperand,
    MissingFixedGate,
    NonCanonicalSelection,
    ProgramDigestMismatch,
    UnsupportedGateExpression,
};

pub const Error = std.mem.Allocator.Error ||
    validator.Error ||
    direct.Error ||
    fixed.Error ||
    ValidationError;

/// An owned, immutable-after-construction lowering result. The hash-consing
/// table remains owned so `deinit` has one unambiguous allocation owner; only
/// the ordered node view is exposed to evaluators.
pub const Program = struct {
    allocator: std.mem.Allocator,
    direct_arena: direct.Arena,
    root_uses: []direct.RootUse,
    materialized_columns: []MaterializedColumn,
    counts: StructuralCounts,
    digest: Digest,

    pub fn deinit(self: *Program) void {
        self.allocator.free(self.materialized_columns);
        self.allocator.free(self.root_uses);
        self.direct_arena.deinit();
        self.* = undefined;
    }

    /// Canonical first-intern node order. Operand IDs index this slice.
    pub fn nodes(self: *const Program) []const Node {
        return self.direct_arena.nodes.items;
    }

    /// Canonical node birth events. Entries correspond one-for-one to
    /// `nodes()` and include interleaved root folds in their event numbers.
    pub fn creationEvents(self: *const Program) []const usize {
        return self.direct_arena.creation_events.items;
    }

    /// Ordered accumulator-fold events, including duplicate node uses.
    pub fn roots(self: *const Program) []const RootUse {
        return self.root_uses;
    }

    /// Ordered semantic-value to physical-column bindings for candidate
    /// materializations. The direct node is the committed leaf in `nodes()`.
    pub fn selectedColumns(self: *const Program) []const MaterializedColumn {
        return self.materialized_columns;
    }

    pub fn programDigest(self: *const Program) Digest {
        return self.digest;
    }

    /// Recomputes the canonical preimage from the exposed program payload and
    /// compares both it and the construction-time digest to trusted identity.
    pub fn authenticate(
        self: *const Program,
        expected: Digest,
    ) ValidationError!void {
        const recomputed = try computeDigest(
            &self.direct_arena,
            self.root_uses,
            self.materialized_columns,
        );
        if (!std.mem.eql(u8, &recomputed, &self.digest) or
            !std.mem.eql(u8, &recomputed, &expected))
        {
            return error.ProgramDigestMismatch;
        }
    }

    /// Payload bytes required by a retained-node interpreter whose scratch
    /// slot is exactly `EvaluationValue`. This deliberately excludes allocator
    /// metadata and alignment padding outside the contiguous value slice.
    pub fn retainedScratchBytes(
        self: *const Program,
        comptime EvaluationValue: type,
    ) error{CountOverflow}!u64 {
        if (@sizeOf(EvaluationValue) == 0)
            @compileError("direct-program scratch values must have non-zero size");
        return std.math.mul(
            u64,
            self.counts.nodes,
            @as(u64, @sizeOf(EvaluationValue)),
        ) catch error.CountOverflow;
    }
};

/// Validates the semantic arena, then extracts its canonical direct program.
pub fn extract(
    allocator: std.mem.Allocator,
    arena: *const ir.Arena,
    request: Request,
) Error!Program {
    try validator.validate(arena);
    return extractValidated(allocator, arena, request);
}

/// Extraction for callers which have already run the canonical IR validator.
/// This exists so a cost search does not validate the same arena twice per
/// candidate; all lowering and direct-program accounting still live here.
pub fn extractValidated(
    allocator: std.mem.Allocator,
    arena: *const ir.Arena,
    request: Request,
) Error!Program {
    try validateRequest(arena, request);

    var direct_arena = direct.Arena.init(allocator);
    errdefer direct_arena.deinit();

    const mapped = try allocator.alloc(u32, arena.nodeCount());
    defer allocator.free(mapped);
    @memset(mapped, no_direct_node);
    const needed = try allocator.alloc(bool, arena.nodeCount());
    defer allocator.free(needed);

    const fixed_root_count: usize = if (request.fixed_direct_program) |program|
        std.math.cast(usize, try program.fixedRootCount()) orelse
            return error.CountOverflow
    else
        0;
    const total_roots = std.math.add(
        usize,
        request.selected.len,
        fixed_root_count,
    ) catch return error.CountOverflow;
    var roots: std.ArrayList(direct.RootUse) = .empty;
    defer roots.deinit(allocator);
    try roots.ensureTotalCapacity(allocator, total_roots);

    const materialized_columns = try allocator.alloc(
        MaterializedColumn,
        request.selected.len,
    );
    errdefer allocator.free(materialized_columns);
    const materialization_tree: fixed.CommitmentTree = if (request.fixed_direct_program) |program|
        program.materialization_tree
    else
        .main;

    const context = try lowerContext(
        &direct_arena,
        arena,
        request.gate,
        request.policy,
        mapped,
    );
    var fixed_lowering: ?fixed.Lowering = if (request.fixed_direct_program) |program|
        try fixed.Lowering.init(allocator, program, request.selected.len)
    else
        null;
    defer if (fixed_lowering) |*lowering| lowering.deinit();
    var fixed_emitter = FixedEmitter{
        .direct_arena = &direct_arena,
        .gate = if (request.gate) |gate| mapped[types.idIndex(gate)] else null,
    };

    if (fixed_lowering) |*lowering| {
        const lowered_roots = try allocator.alloc(u32, lowering.program.prefix_roots.len);
        defer allocator.free(lowered_roots);
        try lowering.lowerPrefix(&fixed_emitter, lowered_roots);
        for (lowered_roots) |root|
            roots.appendAssumeCapacity(try direct_arena.recordRoot(root));
    }

    for (request.selected, 0..) |value, ordinal| {
        const body = try lowerValue(&direct_arena, arena, value, mapped, needed);
        const column = try direct_arena.committed(value, true);
        const equality = try direct_arena.binary(.sub, column, body);
        const root = if (context) |context_node|
            try direct_arena.binary(.mul, equality, context_node)
        else
            equality;
        roots.appendAssumeCapacity(try direct_arena.recordRoot(root));
        mapped[types.idIndex(value)] = column;

        const physical_column = std.math.add(
            u64,
            request.materialization_column_start,
            std.math.cast(u64, ordinal) orelse return error.CountOverflow,
        ) catch return error.CountOverflow;
        materialized_columns[ordinal] = .{
            .source_value = value,
            .tree = materialization_tree,
            .physical_column = physical_column,
            .direct_node = column,
        };
    }

    if (fixed_lowering) |*lowering| {
        const lowered_roots = try allocator.alloc(u32, lowering.program.suffix_roots.len);
        defer allocator.free(lowered_roots);
        try lowering.lowerSuffix(&fixed_emitter, lowered_roots);
        for (lowered_roots) |root|
            roots.appendAssumeCapacity(try direct_arena.recordRoot(root));
    }

    if (roots.items.len != total_roots) return error.CountOverflow;
    const operation_counts = try direct_arena.operationCounts();
    const counts = StructuralCounts{
        .nodes = std.math.cast(u64, direct_arena.nodeCount()) orelse
            return error.CountOverflow,
        .root_uses = std.math.cast(u64, roots.items.len) orelse
            return error.CountOverflow,
        .additions = operation_counts.additions,
        .subtractions = operation_counts.subtractions,
        .negations = operation_counts.negations,
        .multiplications = operation_counts.multiplications,
        .unique_committed_column_reads = operation_counts.committed,
        .streaming_peak_live_nodes = try direct_arena.peakLiveNodes(
            allocator,
            roots.items,
        ),
    };
    const digest = try computeDigest(
        &direct_arena,
        roots.items,
        materialized_columns,
    );

    const owned_roots = try roots.toOwnedSlice(allocator);
    return .{
        .allocator = allocator,
        .direct_arena = direct_arena,
        .root_uses = owned_roots,
        .materialized_columns = materialized_columns,
        .counts = counts,
        .digest = digest,
    };
}

fn validateRequest(arena: *const ir.Arena, request: Request) Error!void {
    if (request.fixed_direct_program) |program| {
        if (request.materialization_column_start !=
            program.materialization_column_start)
        {
            return error.MaterializationColumnStartMismatch;
        }
        const materialization_end = std.math.add(
            u64,
            request.materialization_column_start,
            std.math.cast(u64, request.selected.len) orelse
                return error.CountOverflow,
        ) catch return error.CountOverflow;
        for (program.columns) |column| {
            if (column.tree != program.materialization_tree) continue;
            const resolved = try column.placement.resolve(request.selected.len);
            if (resolved >= request.materialization_column_start and
                resolved < materialization_end)
            {
                return error.FixedColumnAliasesMaterialization;
            }
        }
    }
    if (request.gate) |gate| {
        const node = arena.node(gate) orelse return error.InvalidGate;
        if (!node.key.ty.isSelector()) return error.InvalidGateType;
        switch (node.key.op) {
            .constant, .input, .hint_output, .call_output => {},
            else => return error.UnsupportedGateExpression,
        }
    }
    var previous: ?usize = null;
    for (request.selected) |value| {
        const index = types.idIndex(value);
        const node = arena.node(value) orelse return error.InvalidSelectedValue;
        if (previous) |prior| if (index <= prior)
            return error.NonCanonicalSelection;
        previous = index;
        if (!node.key.ty.isFieldScalar()) return error.InvalidSelectedValueType;
    }
}

const no_direct_node = std.math.maxInt(u32);

const FixedEmitter = struct {
    direct_arena: *direct.Arena,
    gate: ?u32,

    pub fn constant(self: *FixedEmitter, value: u32) Error!u32 {
        return self.direct_arena.intern(.{ .op = .constant, .value = value });
    }

    pub fn column(
        self: *FixedEmitter,
        namespace_digest: *const fixed.Digest,
        column_value: *const fixed.Column,
        resolved: u64,
    ) Error!u32 {
        return switch (column_value.binding) {
            .gate => self.gate orelse error.MissingFixedGate,
            .component => self.direct_arena.fixedCommitted(
                namespace_digest.*,
                column_value.tree,
                resolved,
            ),
        };
    }

    pub fn binary(
        self: *FixedEmitter,
        op: fixed.BinaryOp,
        lhs: u32,
        rhs: u32,
    ) Error!u32 {
        return self.direct_arena.binary(switch (op) {
            .add => .add,
            .sub => .sub,
            .mul => .mul,
        }, lhs, rhs);
    }

    pub fn neg(self: *FixedEmitter, value: u32) Error!u32 {
        return self.direct_arena.intern(.{ .op = .neg, .lhs = value });
    }
};

fn lowerContext(
    direct_arena: *direct.Arena,
    arena: *const ir.Arena,
    gate: ?types.ValueId,
    policy: Policy,
    mapped: []u32,
) Error!?u32 {
    var context: ?u32 = null;
    if (gate) |value| {
        const node = arena.node(value) orelse return error.InvalidGate;
        const lowered = switch (node.key.op) {
            .constant => |constant| try direct_arena.intern(.{
                .op = .constant,
                .value = constantValue(constant),
            }),
            .input, .hint_output, .call_output => try direct_arena.committed(value, false),
            else => return error.UnsupportedGateExpression,
        };
        mapped[types.idIndex(value)] = lowered;
        context = lowered;
    }
    if (policy.row_mask_degree != 0) {
        const mask = try direct_arena.intern(.{
            .op = .row_mask,
            .value = policy.row_mask_degree,
        });
        context = if (context) |prior|
            try direct_arena.binary(.mul, prior, mask)
        else
            mask;
    }
    return context;
}

fn lowerValue(
    direct_arena: *direct.Arena,
    arena: *const ir.Arena,
    root: types.ValueId,
    mapped: []u32,
    needed: []bool,
) Error!u32 {
    const root_index = types.idIndex(root);
    if (mapped[root_index] != no_direct_node) return mapped[root_index];
    @memset(needed, false);
    needed[root_index] = true;
    const root_end = std.math.add(usize, root_index, 1) catch
        return error.CountOverflow;
    var reverse = root_end;
    while (reverse > 0) {
        reverse -= 1;
        if (!needed[reverse] or mapped[reverse] != no_direct_node) continue;
        markOperands(needed, arena.nodesView()[reverse].key.op);
    }

    for (arena.nodesView()[0..root_end], 0..) |node, index| {
        if (!needed[index] or mapped[index] != no_direct_node) continue;
        mapped[index] = switch (node.key.op) {
            .constant => |constant| try direct_arena.intern(.{
                .op = .constant,
                .value = constantValue(constant),
            }),
            .input, .hint_output, .call_output => try direct_arena.committed(
                @enumFromInt(index),
                false,
            ),
            .add => |binary| try direct_arena.binary(
                .add,
                try directOperand(mapped, binary.lhs),
                try directOperand(mapped, binary.rhs),
            ),
            .sub => |binary| try direct_arena.binary(
                .sub,
                try directOperand(mapped, binary.lhs),
                try directOperand(mapped, binary.rhs),
            ),
            .mul => |binary| try direct_arena.binary(
                .mul,
                try directOperand(mapped, binary.lhs),
                try directOperand(mapped, binary.rhs),
            ),
            .neg => |value| try direct_arena.intern(.{
                .op = .neg,
                .lhs = try directOperand(mapped, value),
            }),
            .select => |selection| blk: {
                const selector = try directOperand(mapped, selection.selector);
                const when_true = try directOperand(mapped, selection.when_true);
                const when_false = try directOperand(mapped, selection.when_false);
                const difference = try direct_arena.binary(.sub, when_true, when_false);
                const selected = try direct_arena.binary(.mul, selector, difference);
                break :blk try direct_arena.binary(.add, when_false, selected);
            },
            .machine_derived => |derived| try lowerMachineDerived(
                direct_arena,
                derived,
                mapped,
            ),
        };
    }
    return directOperand(mapped, root);
}

fn markOperands(flags: []bool, op: expr.Op) void {
    switch (op) {
        .constant, .input, .hint_output, .call_output => {},
        .add, .sub, .mul => |binary| {
            flags[types.idIndex(binary.lhs)] = true;
            flags[types.idIndex(binary.rhs)] = true;
        },
        .neg => |value| flags[types.idIndex(value)] = true,
        .select => |selection| {
            flags[types.idIndex(selection.selector)] = true;
            flags[types.idIndex(selection.when_true)] = true;
            flags[types.idIndex(selection.when_false)] = true;
        },
        .machine_derived => |derived| switch (derived) {
            .register_address => |address| flags[types.idIndex(address.index)] = true,
            .aligned_word_address => |address| flags[types.idIndex(address.word_index)] = true,
            .access_clock => |clock| flags[types.idIndex(clock.instruction_clock)] = true,
            .strict_clock_gap => |gap| {
                flags[types.idIndex(gap.current_clock)] = true;
                flags[types.idIndex(gap.previous_clock)] = true;
            },
            .instruction_next_pc => |next| flags[types.idIndex(next.current)] = true,
            .instruction_next_clock => |next| flags[types.idIndex(next.current)] = true,
        },
    }
}

fn lowerMachineDerived(
    direct_arena: *direct.Arena,
    derived: expr.MachineDerived,
    mapped: []const u32,
) Error!u32 {
    return switch (derived) {
        .register_address => |address| directOperand(mapped, address.index),
        .aligned_word_address => |address| blk: {
            const four = try direct_arena.intern(.{ .op = .constant, .value = 4 });
            break :blk direct_arena.binary(
                .mul,
                try directOperand(mapped, address.word_index),
                four,
            );
        },
        .access_clock => |clock| blk: {
            const one = try direct_arena.intern(.{ .op = .constant, .value = 1 });
            const four = try direct_arena.intern(.{ .op = .constant, .value = 4 });
            const phase = try direct_arena.intern(.{
                .op = .constant,
                .value = @intFromEnum(clock.phase),
            });
            const shifted = try direct_arena.binary(
                .sub,
                try directOperand(mapped, clock.instruction_clock),
                one,
            );
            const scaled = try direct_arena.binary(.mul, shifted, four);
            break :blk direct_arena.binary(.add, scaled, phase);
        },
        .strict_clock_gap => |gap| blk: {
            const one = try direct_arena.intern(.{ .op = .constant, .value = 1 });
            const delta = try direct_arena.binary(
                .sub,
                try directOperand(mapped, gap.current_clock),
                try directOperand(mapped, gap.previous_clock),
            );
            break :blk direct_arena.binary(.sub, delta, one);
        },
        .instruction_next_pc => |next| blk: {
            const four = try direct_arena.intern(.{ .op = .constant, .value = 4 });
            break :blk direct_arena.binary(
                .add,
                try directOperand(mapped, next.current),
                four,
            );
        },
        .instruction_next_clock => |next| blk: {
            const one = try direct_arena.intern(.{ .op = .constant, .value = 1 });
            break :blk direct_arena.binary(
                .add,
                try directOperand(mapped, next.current),
                one,
            );
        },
    };
}

fn directOperand(mapped: []const u32, value: types.ValueId) Error!u32 {
    const index = types.idIndex(value);
    if (index >= mapped.len or mapped[index] == no_direct_node)
        return error.MissingDirectOperand;
    return mapped[index];
}

fn constantValue(constant: expr.Constant) u64 {
    return switch (constant) {
        .field => |value| value,
        .unsigned => |value| value,
    };
}

fn computeDigest(
    direct_arena: *const direct.Arena,
    roots: []const direct.RootUse,
    materialized_columns: []const MaterializedColumn,
) ValidationError!Digest {
    if (direct_arena.nodes.items.len != direct_arena.creation_events.items.len)
        return error.CountOverflow;
    var hash = std.crypto.hash.sha2.Sha256.init(.{});
    hash.update(digest_domain);
    hashInt(&hash, u16, format_version);
    hashInt(&hash, u32, std.math.cast(u32, direct_arena.nodes.items.len) orelse
        return error.CountOverflow);
    for (direct_arena.nodes.items, direct_arena.creation_events.items) |node, event| {
        hashInt(&hash, u8, @intFromEnum(node.op));
        hashInt(&hash, u32, node.lhs);
        hashInt(&hash, u32, node.rhs);
        hashInt(&hash, u64, node.value);
        hash.update(&node.namespace_digest);
        hashInt(&hash, u64, std.math.cast(u64, event) orelse
            return error.CountOverflow);
    }
    hashInt(&hash, u32, std.math.cast(u32, roots.len) orelse
        return error.CountOverflow);
    for (roots) |root| {
        hashInt(&hash, u32, root.node);
        hashInt(&hash, u64, std.math.cast(u64, root.fold_event) orelse
            return error.CountOverflow);
    }
    hashInt(&hash, u32, std.math.cast(u32, materialized_columns.len) orelse
        return error.CountOverflow);
    for (materialized_columns) |column| {
        hashInt(&hash, u32, @intFromEnum(column.source_value));
        hashInt(&hash, u8, @intFromEnum(column.tree));
        hashInt(&hash, u64, column.physical_column);
        hashInt(&hash, u32, column.direct_node);
    }
    return hash.finalResult();
}

fn hashInt(hash: anytype, comptime T: type, value: T) void {
    var encoded: [@sizeOf(T)]u8 = undefined;
    std.mem.writeInt(T, &encoded, value, .little);
    hash.update(&encoded);
}

materialization_fixed_direct.zig:
//! Canonical fixed direct-polynomial programs for materialization cost models.
//!
//! A materialization search changes equality boundaries, but a component may
//! also own direct constraints which are independent of that cut. Counting
//! those roots without lowering their expressions makes global DAG, committed
//! read, and live-value costs internally inconsistent. This module represents
//! the fixed expressions as a small validated SSA program and lowers them
//! lazily on either side of the caller-owned materialization equalities.
//!
//! The representation is intentionally independent of the typed semantic
//! arena. A column may explicitly bind to the materialization gate, allowing a
//! target arena to reuse that committed leaf, or name a stable component role.
//! Fixed nodes therefore never enter the semantic witness closure.

const std = @import("std");

pub const Digest = [32]u8;
pub const format_version: u16 = 1;
pub const digest_domain = "stwo-zig/typed-air/fixed-direct-program-v1";
pub const m31_modulus: u32 = 0x7fff_ffff;

pub const max_scope_id_bytes: usize = 128;
pub const max_role_bytes: usize = 96;
pub const max_columns: usize = 4_096;
pub const max_nodes: usize = 65_536;
pub const max_roots_per_phase: usize = 16_384;

pub const NodeId = enum(u32) { _ };

pub const CommitmentTree = enum(u8) {
    preprocessed = 0,
    main = 1,
    interaction = 2,
};

/// How a fixed-program leaf joins the caller's target direct arena.
pub const ColumnBinding = enum(u8) {
    /// The semantic activation value supplied as the materialization gate.
    gate = 0,
    /// A component-owned committed column identified by scope, role and place.
    component = 1,
};

/// Candidate-relative component-local placement in one commitment tree.
pub const Placement = union(enum(u8)) {
    absolute: u32,
    after_materializations: struct {
        /// Number of main columns preceding the candidate materialization block.
        prefix_columns: u32,
        /// Stable offset within the fixed suffix following that block.
        trailing_offset: u32,
    },

    pub fn resolve(self: Placement, materialization_count: u64) Error!u64 {
        return switch (self) {
            .absolute => |index| index,
            .after_materializations => |relative| blk: {
                const after_prefix = std.math.add(
                    u64,
                    relative.prefix_columns,
                    materialization_count,
                ) catch return error.PlacementOverflow;
                break :blk std.math.add(
                    u64,
                    after_prefix,
                    relative.trailing_offset,
                ) catch return error.PlacementOverflow;
            },
        };
    }
};

pub const Column = struct {
    /// Stable, human-reviewable identity within `Program.scope_id`.
    role: []const u8,
    binding: ColumnBinding,
    tree: CommitmentTree,
    placement: Placement,
};

pub const Op = enum(u8) {
    constant = 0,
    column = 1,
    add = 2,
    sub = 3,
    neg = 4,
    mul = 5,
};

pub const BinaryOp = enum(u8) { add, sub, mul };

/// Canonical flat SSA node. Operands must precede their consumer. `value` is
/// the canonical M31 representative for `constant` and a column-table index
/// for `column`; it is zero for arithmetic nodes.
pub const Node = struct {
    op: Op,
    lhs: u32 = 0,
    rhs: u32 = 0,
    value: u32 = 0,
};

pub const Identity = struct {
    format_version: u16,
    scope_id: []const u8,
    scope_version: u16,
    materialization_tree: CommitmentTree,
    materialization_column_start: u32,
    column_count: u32,
    node_count: u32,
    fixed_root_count: u32,
    digest: Digest,
};

pub const ValidationError = error{
    DegreeOverflow,
    DuplicateColumnPlacement,
    DuplicateColumnRole,
    DuplicateGateColumn,
    DuplicateNode,
    EmptyFixedRoots,
    EmptyRole,
    EmptyScopeId,
    InvalidColumn,
    InvalidConstant,
    InvalidNode,
    InvalidRelativePlacement,
    InvalidRoot,
    InvalidScopeVersion,
    NonCanonicalNode,
    PlacementOverflow,
    RoleTooLong,
    ScopeIdTooLong,
    TooManyColumns,
    TooManyNodes,
    TooManyRoots,
    UnsupportedMaterializationTree,
    UnusedColumn,
    UnusedNode,
};

pub const LoweringError = error{
    InvalidDestinationLength,
    InvalidLoweringEmitter,
    InvalidLoweringPhase,
    MissingLoweredOperand,
};

pub const Error = std.mem.Allocator.Error || ValidationError || LoweringError;

/// Borrowed canonical fixed program. Root order is semantic: prefix roots are
/// consumed before caller-owned materialization equalities and suffix roots
/// afterward. Nodes shared by both phases remain mapped in one target arena.
pub const Program = struct {
    scope_id: []const u8,
    scope_version: u16,
    /// Candidate materializations occupy this tree starting at this physical
    /// column. The pair is authenticated even when no fixed column is relative.
    materialization_tree: CommitmentTree,
    materialization_column_start: u32,
    columns: []const Column,
    nodes: []const Node,
    prefix_roots: []const NodeId,
    suffix_roots: []const NodeId,

    pub fn validate(self: Program, allocator: std.mem.Allocator) Error!void {
        if (self.scope_id.len == 0) return error.EmptyScopeId;
        if (self.scope_id.len > max_scope_id_bytes) return error.ScopeIdTooLong;
        if (self.scope_version == 0) return error.InvalidScopeVersion;
        // Cost-frontier v1 accounts candidate materializations as main-trace
        // columns. Keep the tree in the authenticated representation so a
        // later format can extend the model without silently reinterpreting
        // v1 receipts, but reject unsupported trees before authenticating one.
        if (self.materialization_tree != .main)
            return error.UnsupportedMaterializationTree;
        if (self.columns.len > max_columns) return error.TooManyColumns;
        if (self.nodes.len > max_nodes) return error.TooManyNodes;
        if (self.prefix_roots.len > max_roots_per_phase or
            self.suffix_roots.len > max_roots_per_phase)
        {
            return error.TooManyRoots;
        }
        if (self.prefix_roots.len + self.suffix_roots.len == 0)
            return error.EmptyFixedRoots;

        var gate_seen = false;
        for (self.columns, 0..) |column, index| {
            if (column.role.len == 0) return error.EmptyRole;
            if (column.role.len > max_role_bytes) return error.RoleTooLong;
            if (column.binding == .gate) {
                if (gate_seen) return error.DuplicateGateColumn;
                gate_seen = true;
            }
            for (self.columns[0..index]) |prior| {
                if (std.mem.eql(u8, prior.role, column.role))
                    return error.DuplicateColumnRole;
            }
            _ = try column.placement.resolve(0);
            switch (column.placement) {
                .absolute => {},
                .after_materializations => |relative| {
                    if (column.tree != self.materialization_tree or
                        relative.prefix_columns != self.materialization_column_start)
                    {
                        return error.InvalidRelativePlacement;
                    }
                },
            }
        }

        for (self.nodes, 0..) |node, index| {
            try validateNode(node, index, self.columns.len);
            for (self.nodes[0..index]) |prior| {
                if (std.meta.eql(prior, node)) return error.DuplicateNode;
            }
        }

        try validateRoots(self.prefix_roots, self.nodes.len);
        try validateRoots(self.suffix_roots, self.nodes.len);

        const reachable = try allocator.alloc(bool, self.nodes.len);
        defer allocator.free(reachable);
        @memset(reachable, false);
        markRoots(reachable, self.prefix_roots);
        markRoots(reachable, self.suffix_roots);
        var reverse = self.nodes.len;
        while (reverse > 0) {
            reverse -= 1;
            if (!reachable[reverse]) continue;
            markOperands(reachable, self.nodes[reverse]);
        }
        for (reachable) |needed| if (!needed) return error.UnusedNode;

        const used_columns = try allocator.alloc(bool, self.columns.len);
        defer allocator.free(used_columns);
        @memset(used_columns, false);
        for (self.nodes) |node| if (node.op == .column) {
            used_columns[node.value] = true;
        };
        for (used_columns) |used| if (!used) return error.UnusedColumn;
    }

    /// Validates candidate-dependent physical placement in addition to the
    /// canonical program. Equal indices in different commitment trees are
    /// distinct; equal indices in one tree are rejected.
    pub fn validateFor(
        self: Program,
        allocator: std.mem.Allocator,
        materialization_count: u64,
    ) Error!void {
        try self.validate(allocator);
        for (self.columns, 0..) |column, index| {
            const resolved = try column.placement.resolve(materialization_count);
            for (self.columns[0..index]) |prior| {
                if (prior.tree != column.tree) continue;
                if (try prior.placement.resolve(materialization_count) == resolved)
                    return error.DuplicateColumnPlacement;
            }
        }
    }

    pub fn fixedRootCount(self: Program) Error!u32 {
        const count = std.math.add(
            usize,
            self.prefix_roots.len,
            self.suffix_roots.len,
        ) catch return error.TooManyRoots;
        return std.math.cast(u32, count) orelse error.TooManyRoots;
    }

    pub fn totalRootCount(
        self: Program,
        candidate_materialization_roots: u64,
    ) Error!u64 {
        return std.math.add(
            u64,
            candidate_materialization_roots,
            try self.fixedRootCount(),
        ) catch error.TooManyRoots;
    }

    /// Maximum polynomial degree of any ordered fixed root when committed
    /// columns are degree one and constants are degree zero.
    pub fn maximumRootDegree(
        self: Program,
        allocator: std.mem.Allocator,
    ) Error!u64 {
        try self.validate(allocator);
        const degrees = try allocator.alloc(u64, self.nodes.len);
        defer allocator.free(degrees);
        for (self.nodes, degrees) |node, *degree| degree.* = switch (node.op) {
            .constant => 0,
            .column => 1,
            .add, .sub => @max(degrees[node.lhs], degrees[node.rhs]),
            .neg => degrees[node.lhs],
            .mul => std.math.add(u64, degrees[node.lhs], degrees[node.rhs]) catch
                return error.DegreeOverflow,
        };
        var result: u64 = 0;
        for (self.prefix_roots) |root| result = @max(result, degrees[@intFromEnum(root)]);
        for (self.suffix_roots) |root| result = @max(result, degrees[@intFromEnum(root)]);
        return result;
    }

    /// Canonical identity after full validation. Slice contents, never pointer
    /// values or host padding, enter the digest.
    pub fn digestValue(
        self: Program,
        allocator: std.mem.Allocator,
    ) Error!Digest {
        try self.validate(allocator);
        return self.digestValidated();
    }

    pub fn identity(
        self: Program,
        allocator: std.mem.Allocator,
    ) Error!Identity {
        const digest = try self.digestValue(allocator);
        return .{
            .format_version = format_version,
            .scope_id = self.scope_id,
            .scope_version = self.scope_version,
            .materialization_tree = self.materialization_tree,
            .materialization_column_start = self.materialization_column_start,
            .column_count = std.math.cast(u32, self.columns.len) orelse
                return error.TooManyColumns,
            .node_count = std.math.cast(u32, self.nodes.len) orelse
                return error.TooManyNodes,
            .fixed_root_count = try self.fixedRootCount(),
            .digest = digest,
        };
    }

    fn digestValidated(self: Program) Digest {
        var hash = std.crypto.hash.sha2.Sha256.init(.{});
        hash.update(digest_domain);
        hashInt(&hash, u16, format_version);
        hashString(&hash, self.scope_id);
        hashInt(&hash, u16, self.scope_version);
        hashInt(&hash, u8, @intFromEnum(self.materialization_tree));
        hashInt(&hash, u32, self.materialization_column_start);
        hashInt(&hash, u32, @intCast(self.columns.len));
        for (self.columns) |column| {
            hashString(&hash, column.role);
            hashInt(&hash, u8, @intFromEnum(column.binding));
            hashInt(&hash, u8, @intFromEnum(column.tree));
            hashInt(&hash, u8, @intFromEnum(std.meta.activeTag(column.placement)));
            switch (column.placement) {
                .absolute => |index| hashInt(&hash, u32, index),
                .after_materializations => |relative| {
                    hashInt(&hash, u32, relative.prefix_columns);
                    hashInt(&hash, u32, relative.trailing_offset);
                },
            }
        }
        hashInt(&hash, u32, @intCast(self.nodes.len));
        for (self.nodes) |node| {
            hashInt(&hash, u8, @intFromEnum(node.op));
            hashInt(&hash, u32, node.lhs);
            hashInt(&hash, u32, node.rhs);
            hashInt(&hash, u32, node.value);
        }
        hashRoots(&hash, self.prefix_roots);
        hashRoots(&hash, self.suffix_roots);
        return hash.finalResult();
    }
};

pub const LoweringPhase = enum {
    initial,
    lowering_prefix,
    prefix_complete,
    lowering_suffix,
    complete,
    poisoned,
};

/// Candidate-specific lazy lowering state. The emitter must remain the same
/// target arena for both calls and provide:
///
/// - `constant(u32) !u32`
/// - `column(*const Digest, *const Column, u64) !u32`
/// - `binary(BinaryOp, u32, u32) !u32`
/// - `neg(u32) !u32`
///
/// Destination entries are target node IDs in the declared root order.
pub const Lowering = struct {
    allocator: std.mem.Allocator,
    program: Program,
    materialization_count: u64,
    digest: Digest,
    mapped: []u32,
    needed: []bool,
    emitter_address: ?usize = null,
    phase: LoweringPhase = .initial,

    const no_node = std.math.maxInt(u32);

    pub fn init(
        allocator: std.mem.Allocator,
        program: Program,
        materialization_count: u64,
    ) Error!Lowering {
        try program.validateFor(allocator, materialization_count);
        const mapped = try allocator.alloc(u32, program.nodes.len);
        errdefer allocator.free(mapped);
        @memset(mapped, no_node);
        const needed = try allocator.alloc(bool, program.nodes.len);
        errdefer allocator.free(needed);
        return .{
            .allocator = allocator,
            .program = program,
            .materialization_count = materialization_count,
            .digest = program.digestValidated(),
            .mapped = mapped,
            .needed = needed,
        };
    }

    pub fn deinit(self: *Lowering) void {
        self.allocator.free(self.needed);
        self.allocator.free(self.mapped);
        self.* = undefined;
    }

    pub fn programDigest(self: *const Lowering) Digest {
        return self.digest;
    }

    pub fn lowerPrefix(
        self: *Lowering,
        emitter: anytype,
        destination: []u32,
    ) !void {
        if (self.phase != .initial) return error.InvalidLoweringPhase;
        if (destination.len != self.program.prefix_roots.len)
            return error.InvalidDestinationLength;
        try self.bindEmitter(emitter);
        self.phase = .lowering_prefix;
        errdefer self.phase = .poisoned;
        try self.lowerRoots(emitter, self.program.prefix_roots, destination);
        self.phase = .prefix_complete;
    }

    pub fn lowerSuffix(
        self: *Lowering,
        emitter: anytype,
        destination: []u32,
    ) !void {
        if (self.phase != .prefix_complete) return error.InvalidLoweringPhase;
        if (destination.len != self.program.suffix_roots.len)
            return error.InvalidDestinationLength;
        try self.bindEmitter(emitter);
        self.phase = .lowering_suffix;
        errdefer self.phase = .poisoned;
        try self.lowerRoots(emitter, self.program.suffix_roots, destination);
        self.phase = .complete;
    }

    fn lowerRoots(
        self: *Lowering,
        emitter: anytype,
        roots: []const NodeId,
        destination: []u32,
    ) !void {
        for (roots, destination) |root, *lowered| {
            lowered.* = try self.lowerRoot(emitter, root);
        }
    }

    fn lowerRoot(self: *Lowering, emitter: anytype, root: NodeId) !u32 {
        const root_index: usize = @intFromEnum(root);
        if (self.mapped[root_index] != no_node) return self.mapped[root_index];
        @memset(self.needed, false);
        self.needed[root_index] = true;
        var reverse = root_index + 1;
        while (reverse > 0) {
            reverse -= 1;
            if (!self.needed[reverse] or self.mapped[reverse] != no_node) continue;
            markOperands(self.needed, self.program.nodes[reverse]);
        }

        for (self.program.nodes[0 .. root_index + 1], 0..) |node, index| {
            if (!self.needed[index] or self.mapped[index] != no_node) continue;
            self.mapped[index] = switch (node.op) {
                .constant => try emitter.constant(node.value),
                .column => blk: {
                    const column = &self.program.columns[node.value];
                    break :blk try emitter.column(
                        &self.digest,
                        column,
                        try column.placement.resolve(self.materialization_count),
                    );
                },
                .add => try emitter.binary(
                    .add,
                    try operand(self.mapped, node.lhs),
                    try operand(self.mapped, node.rhs),
                ),
                .sub => try emitter.binary(
                    .sub,
                    try operand(self.mapped, node.lhs),
                    try operand(self.mapped, node.rhs),
                ),
                .neg => try emitter.neg(try operand(self.mapped, node.lhs)),
                .mul => try emitter.binary(
                    .mul,
                    try operand(self.mapped, node.lhs),
                    try operand(self.mapped, node.rhs),
                ),
            };
        }
        return operand(self.mapped, @intFromEnum(root));
    }

    fn bindEmitter(self: *Lowering, emitter: anytype) LoweringError!void {
        const address = @intFromPtr(emitter);
        if (self.emitter_address) |bound| {
            if (bound != address) return error.InvalidLoweringEmitter;
        } else {
            self.emitter_address = address;
        }
    }
};

fn validateNode(node: Node, index: usize, column_count: usize) ValidationError!void {
    switch (node.op) {
        .constant => {
            if (node.lhs != 0 or node.rhs != 0) return error.NonCanonicalNode;
            if (node.value >= m31_modulus) return error.InvalidConstant;
        },
        .column => {
            if (node.lhs != 0 or node.rhs != 0) return error.NonCanonicalNode;
            if (node.value >= column_count) return error.InvalidColumn;
        },
        .add, .mul => {
            if (node.value != 0) return error.NonCanonicalNode;
            if (node.lhs >= index or node.rhs >= index) return error.InvalidNode;
            if (node.rhs < node.lhs) return error.NonCanonicalNode;
        },
        .sub => {
            if (node.value != 0) return error.NonCanonicalNode;
            if (node.lhs >= index or node.rhs >= index) return error.InvalidNode;
        },
        .neg => {
            if (node.rhs != 0 or node.value != 0) return error.NonCanonicalNode;
            if (node.lhs >= index) return error.InvalidNode;
        },
    }
}

fn validateRoots(
    roots: []const NodeId,
    node_count: usize,
) ValidationError!void {
    for (roots) |root| {
        if (@intFromEnum(root) >= node_count) return error.InvalidRoot;
    }
}

fn markRoots(reachable: []bool, roots: []const NodeId) void {
    for (roots) |root| reachable[@intFromEnum(root)] = true;
}

fn markOperands(reachable: []bool, node: Node) void {
    switch (node.op) {
        .constant, .column => {},
        .add, .sub, .mul => {
            reachable[node.lhs] = true;
            reachable[node.rhs] = true;
        },
        .neg => reachable[node.lhs] = true,
    }
}

fn operand(mapped: []const u32, raw: u32) LoweringError!u32 {
    if (raw >= mapped.len or mapped[raw] == Lowering.no_node)
        return error.MissingLoweredOperand;
    return mapped[raw];
}

fn hashRoots(hash: anytype, roots: []const NodeId) void {
    hashInt(hash, u32, @intCast(roots.len));
    for (roots) |root| hashInt(hash, u32, @intFromEnum(root));
}

fn hashString(hash: anytype, value: []const u8) void {
    hashInt(hash, u16, @intCast(value.len));
    hash.update(value);
}

fn hashInt(hash: anytype, comptime T: type, value: T) void {
    var bytes: [@sizeOf(T)]u8 = undefined;
    std.mem.writeInt(T, &bytes, value, .little);
    hash.update(&bytes);
}

typed_poseidon2_fixed_direct.zig:
//! Exact fixed direct-polynomial profile for the typed Poseidon2 pilot.
//!
//! Scope is deliberately the permutation direct AIR, not the surrounding
//! RISC-V hash-component shell or its LogUp interaction constraints. The
//! caller inserts candidate materialization equalities between the prefix and
//! suffix roots.

const fixed = @import("materialization_fixed_direct.zig");
const compat = @import("typed_poseidon2_compat.zig");

pub const cost_scope_id = "stwo.typed-air.cost.poseidon2-permutation-direct";
pub const cost_scope_version: u16 = 1;
pub const width: u32 = compat.WIDTH;
pub const fixed_root_count: u32 = 4;
pub const main_prefix_columns: u32 = compat.TEMPORARY_START;
pub const canonical_digest: fixed.Digest = .{
    0xef, 0x32, 0x02, 0x4b, 0xa1, 0xd2, 0x5b, 0x47,
    0x0c, 0x21, 0x7e, 0xf9, 0x6a, 0xf9, 0x5b, 0x52,
    0x03, 0x89, 0x48, 0xc6, 0x7f, 0x6a, 0xc4, 0xce,
    0x1e, 0x14, 0x87, 0x5b, 0xf6, 0x8e, 0xa6, 0xa5,
};

pub const ColumnIndex = enum(u32) {
    enabler = 0,
    wide = 1,
    io = 2,
};

pub const columns = [_]fixed.Column{
    .{
        .role = "enabler",
        .binding = .gate,
        .tree = .main,
        .placement = .{ .absolute = 0 },
    },
    .{
        .role = "wide",
        .binding = .component,
        .tree = .main,
        .placement = .{ .after_materializations = .{
            .prefix_columns = main_prefix_columns,
            .trailing_offset = 0,
        } },
    },
    .{
        .role = "io",
        .binding = .component,
        .tree = .main,
        .placement = .{ .after_materializations = .{
            .prefix_columns = main_prefix_columns,
            .trailing_offset = 1,
        } },
    },
};

/// Topological node order also fixes first-intern evaluation order:
///
/// `e`, `1`, `1-e`, `e(1-e)`, then after candidate equalities
/// `wide`, `1-wide`, `wide(1-wide)`, `io`, `1-io`, `io(1-io)`, `wide*io`.
pub const nodes = [_]fixed.Node{
    .{ .op = .column, .value = @intFromEnum(ColumnIndex.enabler) },
    .{ .op = .constant, .value = 1 },
    .{ .op = .sub, .lhs = 1, .rhs = 0 },
    .{ .op = .mul, .lhs = 0, .rhs = 2 },
    .{ .op = .column, .value = @intFromEnum(ColumnIndex.wide) },
    .{ .op = .sub, .lhs = 1, .rhs = 4 },
    .{ .op = .mul, .lhs = 4, .rhs = 5 },
    .{ .op = .column, .value = @intFromEnum(ColumnIndex.io) },
    .{ .op = .sub, .lhs = 1, .rhs = 7 },
    .{ .op = .mul, .lhs = 7, .rhs = 8 },
    .{ .op = .mul, .lhs = 4, .rhs = 7 },
};

pub const prefix_roots = [_]fixed.NodeId{@enumFromInt(3)};
pub const suffix_roots = [_]fixed.NodeId{
    @enumFromInt(6),
    @enumFromInt(9),
    @enumFromInt(10),
};

pub const program = fixed.Program{
    .scope_id = cost_scope_id,
    .scope_version = cost_scope_version,
    .materialization_tree = .main,
    .materialization_column_start = main_prefix_columns,
    .columns = &columns,
    .nodes = &nodes,
    .prefix_roots = &prefix_roots,
    .suffix_roots = &suffix_roots,
};

comptime {
    if (columns.len != 3 or nodes.len != 11 or
        prefix_roots.len + suffix_roots.len != fixed_root_count or
        compat.ENABLER_COLUMN != 0 or compat.N_MATERIALIZATIONS != 426 or
        compat.WIDE_COLUMN != main_prefix_columns + compat.N_MATERIALIZATIONS or
        compat.IO_COLUMN != compat.WIDE_COLUMN + 1)
    {
        @compileError("Poseidon2 fixed direct profile geometry drifted");
    }
}
